 function expandDescriptionOnHover(event:MouseEvent<HTMLElement>,key:string){const description=event.currentTarget.querySelector<HTMLElement>('.card-description-overlay');if(!description)return;const display=description.style.display,clamp=description.style.webkitLineClamp,overflow=description.style.overflow;const visibleHeight=description.getBoundingClientRect().height;description.style.display='block';description.style.webkitLineClamp='unset';description.style.overflow='visible';const fullHeight=description.getBoundingClientRect().height;description.style.display=display;description.style.webkitLineClamp=clamp;description.style.overflow=overflow;if(visibleHeight>0&&fullHeight>visibleHeight+2)setExpandedDescriptionKey(key)}
 function playCardleClueSequence(context:AudioContext,feedback:CardleFeedback,winning=false){
  const delays=winning?[0,.28,.56,.84,1.12]:[.25,1.1,1.95,2.8,3.65],keys=['nameLength','rarity','series','category','booster'] as const;
  const tones:Record<CardleHint,{from:number;to:number;duration:number;volume:number;wave:OscillatorType}>={
   correct:{from:500,to:660,duration:.13,volume:.052,wave:'sine'},
   wrong:{from:250,to:185,duration:.095,volume:.043,wave:'triangle'},
   higher:{from:315,to:515,duration:.14,volume:.05,wave:'triangle'},
   lower:{from:515,to:315,duration:.14,volume:.05,wave:'triangle'}
  };
  try{
   keys.forEach((key,index)=>{
    const tone=tones[feedback[key]],start=context.currentTime+delays[index],oscillator=context.createOscillator(),gain=context.createGain();
    oscillator.type=tone.wave;oscillator.frequency.setValueAtTime(tone.from,start);oscillator.frequency.exponentialRampToValueAtTime(tone.to,start+tone.duration);
    gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(tone.volume,start+.008);gain.gain.exponentialRampToValueAtTime(.0001,start+tone.duration);
    oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+tone.duration+.01);
   });
   if(winning){[659,784,988].forEach((frequency,index)=>{const start=context.currentTime+1.35+index*.12,oscillator=context.createOscillator(),gain=context.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.035,start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+.24);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+.25)})}
   window.setTimeout(()=>void context.close().catch(()=>{}),Math.ceil((winning?2.05:delays[delays.length-1]+.25)*1000));
  }catch{void context.close().catch(()=>{})}
 }
 function playBlurredGuessSound(correct:boolean){
  if(!soundEnabled||typeof window==='undefined')return;
  let context:AudioContext|null=null;
  try{
   context=new window.AudioContext();void context.resume().catch(()=>{});
   const notes=correct?[{frequency:523,duration:.14,delay:0},{frequency:698,duration:.18,delay:.09},{frequency:880,duration:.24,delay:.2}]:[{frequency:270,duration:.13,delay:0},{frequency:205,duration:.18,delay:.1}];
   notes.forEach(note=>{const start=context!.currentTime+note.delay,oscillator=context!.createOscillator(),gain=context!.createGain();oscillator.type=correct?'sine':'triangle';oscillator.frequency.setValueAtTime(note.frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(correct?0.045:0.035,start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+note.duration);oscillator.connect(gain);gain.connect(context!.destination);oscillator.start(start);oscillator.stop(start+note.duration+.01)});
   window.setTimeout(()=>void context?.close().catch(()=>{}),650);
  }catch{void context?.close().catch(()=>{})}
 }
 async function submitCardleGuess(cardId:string){if(cardleSubmitting)return;let clueAudio:AudioContext|null=null;if(soundEnabled&&typeof window!=='undefined'){try{clueAudio=new window.AudioContext();void clueAudio.resume().catch(()=>{})}catch{clueAudio=null}}setCardleSubmitting(true);setCardleError('');try{const response=await fetch('/api/demo/cardle',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({cardId})});const data=await response.json();if(!response.ok)throw new Error(data.error??'Proposition refusée.');const game=data as CardleState;setCardleState(game);setCardleRevealGuessId(game.guesses[game.guesses.length-1]?.card.id??null);setCardleSearch('');if(game.solved)void refreshPlayerState();else requestAnimationFrame(()=>cardleSearchInputRef.current?.focus());if(clueAudio){playCardleClueSequence(clueAudio,game.guesses[game.guesses.length-1].feedback,game.solved);clueAudio=null}}catch(error){if(clueAudio)void clueAudio.close().catch(()=>{});setCardleError(error instanceof Error?error.message:'Impossible d’enregistrer la proposition.');requestAnimationFrame(()=>cardleSearchInputRef.current?.focus())}finally{if(clueAudio)void clueAudio.close().catch(()=>{});setCardleSubmitting(false)}}
 async function resetCardle(){if(cardleResetting||cardleSubmitting)return;setCardleResetting(true);setCardleError('');try{const response=await fetch('/api/demo/cardle',{method:'DELETE',credentials:'same-origin'});const data=await response.json();if(!response.ok)throw new Error(data.error??'Réinitialisation refusée.');setCardleState(data as CardleState);setCardleRevealGuessId(null);setCardleSearch('')}catch(error){setCardleError(error instanceof Error?error.message:'Impossible de réinitialiser la partie.')}finally{setCardleResetting(false)}}
 async function submitBlurredGuess(cardId:string){if(blurredSubmitting)return;setBlurredSubmitting(true);setBlurredError('');try{const response=await fetch('/api/demo/blurred-card',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({cardId})});const data=await response.json();if(!response.ok)throw new Error(data.error??'Proposition refusée.');const game=data as BlurredState;setBlurredState(game);setBlurredSearch('');playBlurredGuessSound(game.solved);if(game.solved)void refreshPlayerState();else requestAnimationFrame(()=>blurredSearchInputRef.current?.focus())}catch(error){setBlurredError(error instanceof Error?error.message:'Impossible d’enregistrer la proposition.');requestAnimationFrame(()=>blurredSearchInputRef.current?.focus())}finally{setBlurredSubmitting(false)}}
 async function resetBlurredGame(){if(blurredResetting||blurredSubmitting)return;setBlurredResetting(true);setBlurredError('');try{const response=await fetch('/api/demo/blurred-card',{method:'DELETE',credentials:'same-origin'});const data=await response.json();if(!response.ok)throw new Error(data.error??'Réinitialisation refusée.');setBlurredState(data as BlurredState);setBlurredSearch('')}catch(error){setBlurredError(error instanceof Error?error.message:'Impossible de réinitialiser la partie.')}finally{setBlurredResetting(false)}}
