 async function auth(){
  const schema=authMode==='signin'
   ? z.object({email:z.string().email('Adresse e-mail invalide'),password:z.string().min(1,'Saisissez votre mot de passe')})
   : z.object({email:z.string().email('Adresse e-mail invalide').refine(value=>value.toLowerCase().endsWith('@epitech.eu'),'Utilise une adresse e-mail @epitech.eu'),password:z.string().min(8,'Le mot de passe doit contenir au moins 8 caractères'),username:z.string().trim().min(3,'Le pseudo doit contenir au moins 3 caractères').max(24,'Le pseudo doit contenir 24 caractères maximum').regex(/^[a-zA-Z0-9_-]+$/,'Utilisez lettres, chiffres, _ ou -')});
  const parsed=schema.safeParse(authMode==='signin'?{email,password}:{email,password,username:username.trim()});
  if(!parsed.success)return setLoginError(parsed.error.issues[0]?.message??'Informations invalides.');
  const response=await fetch(`/api/auth/${authMode==='signin'?'signin':'signup'}`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(parsed.data)});
  const data=await response.json();if(!response.ok)return setLoginError(data.error??'Impossible de se connecter.');
  setUser(data.user);setShowAuth(false);setLoginError('');setNotice(authMode==='signin'?'Connexion réussie.':'Compte créé. Bienvenue dans Epicards.');
 }
